def _guess_area(bands, intensities, loc):
  idx = np.searchsorted(bands, loc)
  i, j = max(0, idx-4), idx+5
  area_guess = scipy.integrate.trapz(intensities[i:j], bands[i:j])
  return max(0, area_guess)
